fn solve(n: i8, m: i8) -> (i8, i8) {
    // The second component is the smaller of n and m.
    let second = n.min(m);
    // The first component is (n + m - 1) minus the second component,
    // which equivalently is the larger of n and m minus 1.
    let first = n + m - 1 - second;
    (first, second)
}

